def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        ns = int(nanoseconds)
    except Exception:
        raise TypeError("nanoseconds must be an integer or convertible to int")
    if ns < 0:
        raise ValueError("nanoseconds must be non-negative")
    sec, nano_rem = divmod(ns, 1_000_000_000)
    hour, rem = divmod(sec, 3600)
    minute, second = divmod(rem, 60)
    microsecond = nano_rem // 1000
    from datetime import datetime, timezone, timedelta
    if tz is None:
        return datetime(1970, 1, 1, hour, minute, second, microsecond).time()
    # Determine tzinfo from tz argument
    tzinfo = None
    if isinstance(tz, str):
        # Try zoneinfo first (Python 3.9+)
        try:
            from zoneinfo import ZoneInfo
            tzinfo = ZoneInfo(tz)
        except Exception:
            # Fallback: interpret string as integer offset in seconds
            try:
                offset_sec = int(tz)
                tzinfo = timezone(timedelta(seconds=offset_sec))
            except Exception:
                raise ValueError(f"Invalid timezone string: {tz}") from None
    elif isinstance(tz, (timezone, type(timezone.utc))):
        tzinfo = tz
    else:
        # Assume tz is already a tzinfo-like object
        tzinfo = tz
    try:
        return datetime(
            1970, 1, 1, hour, minute, second, microsecond, tzinfo=tzinfo
        ).time()
    except Exception as exc:
        raise ValueError(f"Could not create time with tz={tz}") from exc

