def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    if not hasattr(value, "total_seconds"):
        raise TypeError("value must be a datetime.timedelta instance")
    total_seconds = value.total_seconds()
    # If the total seconds is an integer, return it as an int for compactness
    if abs(total_seconds - int(total_seconds)) < 1e-9:
        return int(total_seconds)
    # Otherwise, return a dictionary representation that preserves full detail
    return {
        "days": value.days,
        "seconds": value.seconds,
        "microseconds": getattr(value, "microseconds", 0),
    }

