def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    # Ensure cmd is a tuple of strings
    if not isinstance(cmd, (tuple, list)):
        raise TypeError("cmd must be a tuple or list of strings")
    # Prepare base command
    base_cmd = list(cmd)

    # Determine partitions of arguments
    target_concurrency = max(1, target_concurrency)
    partitions: list[tuple[str, ...]] = []

    if not varargs:
        partitions = [()]
    else:
        # Chunk varargs into roughly equal sized groups guaranteeing number of groups <= target_concurrency
        step = (len(varargs) + target_concurrency - 1) // target_concurrency
        for i in range(0, len(varargs), step):
            partitions.append(tuple(varargs[i:i + step]))

    # Function to run a single command partition
    def _run_one(part: tuple[str, ...]) -> tuple[int, bytes, bytes]:
        args = tuple(base_cmd) + part
        # If color requested, try to allocate a pseudo-terminal on supported platforms
        env_kwargs = {}
        if color:
            try:
                import os
                env_kwargs = {"preexec_fn": os.setsid}
            except Exception:
                env_kwargs = {}
        try:
            with subprocess.Popen(
                args,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                **{**kwargs, **env_kwargs},
            ) as proc:
                out, err = proc.communicate()
                return proc.returncode, out, err
        except FileNotFoundError:
            # Command not found
            return 127, b"", b""
        except Exception:
            # Any other exception results in a non-zero return code
            return 1, b"", b""

    # Execute partitions, possibly in parallel
    retcode = 0
    stdout_parts = []

    if len(partitions) == 1:
        rc, out, err = _run_one(partitions[0])
        retcode |= rc
        stdout_parts.append(out)
    else:
        # Use a thread pool to parallelize execution
        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as pool:
            futures = [pool.submit(_run_one, p) for p in partitions]
            for f in concurrent.futures.as_completed(futures):
                try:
                    rc, out, err = f.result()
                except Exception:
                    rc, out, err = 1, b"", b""
                retcode |= rc
                stdout_parts.append(out)

    return retcode, b"".join(stdout_parts)

