    partitions: list[list[str]] = []
    if len(varargs) == 0:
        partitions = [[]]
    else:
        # Simple round‑robin splitting into `target_concurrency` chunks
        for i in range(target_concurrency):
            partitions.append(list(varargs[i::target_concurrency]))
        # Filter out empty partitions that may arise if varargs < target_concurrency
        partitions = [p for p in partitions if p]

