    def _run_partition(args: list[str]) -> tuple[int, bytes]:
        full_cmd = list(cmd) + args
        # If pty is used, we attach the slave to stdin; otherwise normal run
        try:
            if pty_slave is not None:
                result = subprocess.run(
                    full_cmd,
                    stdin=pty_slave,
                    capture_output=True,
                    **kwargs
                )
            else:
                result = subprocess.run(
                    full_cmd,
                    capture_output=True,
                    **kwargs
                )
        except FileNotFoundError:
            # Convert subprocess exception into a common format
            raise FileNotFoundError(f"Command not found: {full_cmd[0]}")
        except Exception as exc:
            # Re‑raise any other exception so callers know something went wrong
            raise exc
