def parse_version(s: str) -> tuple[int, ...]:
    """Poor man's version comparison.

    Splits the supplied version string on periods and attempts to
    convert each component to an integer. Non-numeric components are
    ignored. Leading ``v`` characters are stripped. Raises a
    ``ValueError`` if no numeric parts could be extracted.
    """
    if not isinstance(s, str):
        raise TypeError('s must be a str')
    # Strip a leading 'v' or 'V' if present.
    if s.lower().startswith('v'):
        s = s[1:]
    parts = s.split('.')
    nums = []
    for part in parts:
        try:
            nums.append(int(part))
        except ValueError:
            # Try to grab a leading integer, ignoring any suffix.
            num_str = ''
            for ch in part:
                if ch.isdigit():
                    num_str += ch
                else:
                    break
            if num_str:
                nums.append(int(num_str))
    if not nums:
        raise ValueError(f'No numeric components found in version string {s!r}')
    return tuple(nums)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str) or not s:
        raise ValueError(f"Invalid version string: {s!r}")
    import re
    parts = re.findall(r'\d+', s)
    if not parts:
        raise ValueError(f"No numeric components found in version string: {s!r}")
    try:
        nums = tuple(int(part) for part in parts)
    except ValueError as exc:
        raise ValueError(f"Error parsing numeric components in {s!r}") from exc
    return nums

