def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    # Only modify on Windows
    if not sys.platform.startswith('win'):
        return cmd

    cmd_list = list(cmd)

    # Resolve the first argument (possible script path)
    if cmd_list:
        arg0 = cmd_list[0]
        # Expand user and get absolute path
        try:
            abs_path = os.path.abspath(os.path.expanduser(arg0))
        except Exception:
            abs_path = arg0

        # Check for shebang in the script file
        if os.path.isfile(abs_path):
            try:
                with open(abs_path, 'r', encoding='utf-8', errors='ignore') as f:
                    first_line = f.readline()
                if first_line.startswith('#!'):
                    # Split shebang line into interpreter and optional args
                    shebang = first_line[2:].strip()
                    parts = shlex.split(shebang, posix=False)
                    if parts:
                        interpreter = parts[0]
                        # Resolve interpreter path
                        if not os.path.isabs(interpreter):
                            # Look up in PATH first
                            interp_abs = shutil.which(interpreter)
                            if interp_abs is None:
                                # Fall back to script directory
                                interp_abs = os.path.join(os.path.dirname(abs_path), interpreter)
                        else:
                            interp_abs = interpreter
                        # Quote interpreter if it contains spaces
                        if ' ' in interp_abs and not (interp_abs.startswith('"') and interp_abs.endswith('"')):
                            interp_abs = f'"{interp_abs}"'
                        she

