def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.
    A base class is omitted if it is a superclass of any other class in the list.
    The resulting list preserves the relative order of the minimal classes
    as they appeared in the input.
    """
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of class types")
    result = []
    for cls in classes:
        # Skip non-classes
        if not isinstance(cls, type):
            raise TypeError(f"expected a class type, got {type(cls).__name__}")
        # Skip duplicates
        if cls in result:
            continue
        # Determine if this class should replace or be discarded
        replace = []  # classes to remove because they are superclasses of cls
        skip = False
        for existing in result:
            try:
                if issubclass(exists, cls):
                    # Existing is more derived; keep existing, drop cls
                    skip = True
                    break
                if issubclass(cls, existing):
                    # cls is more derived; mark existing for removal
                    replace.append(existing)
            except Exception:
                # In case of unusual inheritance structures, skip graceful handling
                skip = True
                break
        if skip:
            continue
        for ex in replace:
            result.remove(ex)
        result.append(cls)
    return result

