def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
           Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Prepare a list of CSV lines
    lines = []

    # Optional header
    if header is not None:
        lines.append(str(header))

    try:
        # Determine how to iterate over points
        # Prefer explicit iterator, fall back to __iter__
        if hasattr(self, 'points'):
            points_iter = self.points
        elif hasattr(self, 'items'):
            points_iter = self.items()
        else:
            points_iter = self

        for point in points_iter:
            # Attempt to unpack into coordinate and value
            if isinstance(point, (tuple, list)) and len(point) >= 2:
                coords, value = point[0], point[1]
            else:
                # If point is not a tuple/list, treat the whole as coords
                coords, value = point, None

            # Convert coordinates to strings
            if hasattr(coords, '__iter__') and not isinstance(coords, (str, bytes)):
                coord_parts = [str(c) for c in coords]
            else:
                coord_parts = [str(coords)]

            # Convert value to strings
            if value is None:
                val_parts = []
            else:
                if hasattr(value, '__iter__') and not isinstance(value, (str, bytes)):
                    val_parts = [str(v) for v in value]
                else:
                    val_parts = [str(value)]

            # Build the CSV row
            row = coord_parts + val_parts
            lines.append(separator.join(row))

    except Exception as exc:
        raise RuntimeError(f"Failed to convert graph to CSV: {exc}") from exc

    # Join lines into final CSV string
    return "\n".join(lines) + ("\n" if lines else "")

