def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input type
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # Candidate attributes that may hold error indices
    possible_attrs = ["_err_indices", "error_indices", "errors", "error_idx", "err_idx", "error_index"]

    err = None
    # Search for a suitable container
    for attr in possible_attrs:
        if hasattr(self, attr):
            container = getattr(self, attr)
            # If container is a dict, try to get the entry
            if isinstance(container, dict):
                err = container.get(coord_name, None)
                if err is not None:
                    break
            # If container has get method (e.g., an OrderedDict)
            elif hasattr(container, "get") and callable(container.get):
                err = container.get(coord_name, None)
                if err is not None:
                    break
            # If container is an object with an attribute named coord_name
            elif hasattr(container, coord_name):
                err = getattr(container, coord_name)
                if err is not None:
                    break

    if err is None:
        raise KeyError(f"Error indices for coordinate '{coord_name}' not found")

    # If err is an iterable (but not a string/bytes), try to convert to list
    if hasattr(err, "__iter__") and not isinstance(err, (str, bytes)):
        # Handle boolean masks
        try:
            if all(isinstance(v, bool) for v in err):
                # Return indices where mask is True
                return [i for i, val in enumerate(err) if val]
        except TypeError:
            # err is not iterable, treat as single value
            pass

        # Convert iterable to list
        return list(err)

    # For a single non-iterable value, wrap it in a list
    return [err]

