def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Ensure inputs are numpy arrays for vectorised operations
    try:
        import numpy as np
    except ImportError as exc:
        raise RuntimeError("NumPy is required for integral calculation") from exc

    bins = np.asarray(bins, dtype=np.float64)
    edges = np.asarray(edges, dtype=np.float64)

    if bins.ndim != 1:
        raise ValueError(f"Expected 1‑D sequence for bins, got shape {bins.shape}")

    if edges.ndim != 1:
        raise ValueError(f"Expected 1‑D sequence for edges, got shape {edges.shape}")

    if len(edges) != len(bins) + 1:
        raise ValueError(
            f"Number of edges ({len(edges)}) must be one more than number of bins ({len(bins)})"
        )

    # Compute bin widths
    widths = np.diff(edges)

    # Integral of histogram is sum over bins times bin widths
    return np.sum(bins * widths, dtype=np.float64)

