def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure the histogram has been initialized
    if not hasattr(self, "_edges") or not hasattr(self, "_data"):
        raise AttributeError(
            "Histogram must have '_edges' and '_data' attributes prior to calling fill."
        )

    # Convert to numpy arrays
    coord = np.asarray(coord)
    weight = np.asarray(weight)

    # Ensure coord has the right dimensionality
    if coord.ndim == 0:  # scalar coordinate
        coord = coord.reshape(1)
    if coord.ndim > 1:
        # if coord is a list of coordinates, ensure shape (..., dims)
        if coord.shape[-1] != len(self._edges):
            raise ValueError(
                f"Coordinate shape {coord.shape} does not match number of histogram "
                f"dimensions {len(self._edges)}."
            )
    else:
        # 1D coordinate
        if coord.size != len(self._edges):
            raise ValueError(
                f"Coordinate size {coord.size} does not match number of histogram "
                f"dimensions {len(self._edges)}."
            )

    # Flatten coordinates to iterate over each point
    if coord.ndim == 1:
        # single point
        points = coord.reshape(1, -1)
    else:
        points = coord.reshape(-1, len(self._edges))

    # Ensure weight is broadcastable to the number of points
    try:
        weight = np.broadcast_to(weight, points.shape[0])
    except ValueError:
        if weight.size == 1:
            weight = np.full(points.shape[0], weight.item())
        else:
            raise ValueError(
                f"Weight shape {weight.shape} cannot be broadcast to number of coordinates."
            )

    # Find bin indices for each point in each dimension
    bin_indices = []
    for dim, edges in enumerate(self._edges):
        # searchsorted returns index where value should be inserted to maintain order
        # 'right' ensures that values equal to edges[-1] go to the last bin
        idx = np.searchsorted(edges, points[:, dim], side="right") - 1
        bin_indices.append(idx)

    bin_indices = np.vstack(bin_indices).T  # shape (n_points, n_dims)

    # Mask points that fall outside the histogram edges
    mask = np.logical_and.reduce(
