    # Simple regex patterns: key must start with a letter, follow by letters, digits or underscores
    key_regex = re.compile(r'^[A-Za-z][A-Za-z0-9_]*$')
    # Value regex is same for illustration; adjust as needed
    value_regex = re.compile(r'^[A-Za-z][A-Za-z0-9_]*$')

    errors = []

    def _add_error(item_repr, msg):
        errors.append({item_repr: msg})

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            _add_error(repr(key), 'expected string or bytes-like object')
        else:
            if not key_regex.match(key):
                _add_error(key, f"Label key '{key}' does not match the regex [...]")

        # Helper to validate a single value
