    if not hasattr(app, 'spec'):
        raise ValueError("Application object must have a 'spec' attribute")
    spec = getattr(app, 'spec')
    if not hasattr(spec, 'manifest'):
        raise ValueError("Application spec must contain a 'manifest' attribute")
    if not hasattr(spec, 'observer_schema'):
        # If no observer_schema entry exists, initialize an empty dict
        spec.observer_schema = {}

    # Collect the set of resource kinds present in the manifest
    try:
        manifest = spec.manifest
    except Exception as exc:
        raise ValueError(f"Unable to access manifest: {exc}") from exc

    if not isinstance(manifest, dict):
        raise TypeError("spec.manifest should be a dictionary of resources")

    # Prepare a dictionary to hold default schemas for missing resources
    default_schemas = {}

    for resource_kind in manifest.keys():
        if resource_kind not in spec.observer_schema:
            # Produce a minimal default observer schema
            # Using a generic JSON schema that accepts any object
            default_schema = {
                "type": "object",
                "properties": {},
                "additionalProperties": True
            }
            # Store the default in the application's observer_schema dict
            spec.observer_schema[resource_kind] = default_schema
            default_schemas[resource_kind] = default_schema

    return default_schemas

