def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os

    if not path:
        return False

    try:
        abs_path = os.path.abspath(path)
    except Exception:
        return False

    if not os.path.isdir(abs_path):
        return False

    # Basic OCFL structure checks
    ocfl_version_file = os.path.join(abs_path, '.ocfl-version')
    if not os.path.isfile(ocfl_version_file):
        return False

    object_dir = os.path.join(abs_path, 'object')
    if not os.path.isdir(object_dir):
        return False

    # Ensure at least one incarnation exists
    try:
        inc_dirs = [d for d in os.listdir(object_dir)
                    if os.path.isdir(os.path.join(object_dir, d))]
    except Exception:
        return False

    if not inc_dirs:
        return False

    return True

