        manifest_in_root = os.path.join(path, 'manifest.json')
        if os.path.exists(manifest_in_root):
            return True

        # Fallback: look for any '.manifest' file in the root directory
        for entry in os.listdir(path):
            if entry.endswith('.manifest'):
                return True
        # If nothing found, consider the object invalid
        return False
    except Exception:
        # Any exception during validation results in an invalid object
        return False

