    # Assuming version strings can be sorted alphabetically for ordering
    all_versions = sorted([v for v in inventory if isinstance(v, str)])
    try:
        start_index = all_versions.index(version)
    except ValueError:
        raise KeyError(f"Version '{version}' not found in inventory list")

    # Gather logical paths from the requested version
    result = {}
    base_mapping = inventory.get(version, {})
