def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None or not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping logical paths to nested dictionaries")
    if version is None:
        raise ValueError("version must be provided")
    result = {}
    def _version_tuple(v):
        try:
            return tuple(int(p) for p in str(v).split('.') if p.isdigit())
        except Exception:
            return ()
    target = _version_tuple(version)
    for logical_path, ver_map in inventory.items():
        if not isinstance(ver_map, dict):
            continue
        files = set()
        for ver_key, content in ver_map.items():
            # Only include files from the given version or later ones
            try:
                v_tuple = _version_tuple(ver_key)
            except Exception:
                v_tuple = ()
            if v_tuple and target and v_tuple < target:
                continue
            # v_tuple empty means non-numeric version, fallback to string comparison
            if target and v_tuple and (not v_tuple):
                if str(ver_key) < str(version):
                    continue
            if isinstance(content, (set, list, tuple)):
                files.update(content)
            else:
                files.add(content)
        if files:
            result[logical_path] = files
    return result

