def files_list(path):
    """
    Return the files in `path`
    """
    import os

    # Validate that the path exists
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")

    # If the path is a file, return its absolute path
    if os.path.isfile(path):
        return [os.path.abspath(path)]

    # If the path is a directory, gather all files recursively
    if os.path.isdir(path):
        files = []
        try:
            for root, _, filenames in os.walk(path):
                for filename in filenames:
                    files.append(os.path.join(root, filename))
        except (OSError, PermissionError) as exc:
            # Handle permission errors or other OS-related issues gracefully
            raise IOError(f"Error accessing contents of directory '{path}': {exc}")
        return files

    # If the type is neither file nor directory (e.g., special file), return empty list
    return []

