def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping from package base name to a dict with keys:
        - 'xml': path to the XML file (if present)
        - 'others': list of paths to non-xml files sharing the same base name
    """
    packages = {}
    if not isinstance(folder, str):
        raise TypeError('folder must be a string path')
    if not os.path.isdir(folder):
        # If the folder does not exist we return an empty dict
        return packages

    # Build a mapping from basename to list of file paths
    base_to_paths = {}
    try:
        for root, _, files in os.walk(folder):
            for f in files:
                base, _ = os.path.splitext(f)
                path = os.path.join(root, f)
                base_to_paths.setdefault(base, []).append(path)
    except (OSError, PermissionError) as exc:
        # Log or re-raise as appropriate; here we return whatever was found so far
        return packages

    # Only keep bases that have at least one XML file
    for base, paths in base_to_paths.items():
        xml_files = [p for p in paths if p.lower().endswith('.xml')]
        if not xml_files:
            continue
        packages[base] = {
            'xml': xml_files[0],          # first XML file found
            'others': [p for p in paths if p not in xml_files]
        }

    return packages

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their basename (derived from the XML file) and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
        A dictionary where the key is the basename (without extension) of the XML file
        and the value is a list of full file paths belonging to that package.
    """
    import os
    if not isinstance(folder, str):
        raise TypeError("folder must be a string representing a path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder not found: {folder}")

    package_files = {}
    try:
        for root, _, files in os.walk(folder):
            for filename in files:
                # Skip hidden files
                if filename.startswith('.'):
                    continue
                base_name, ext = os.path.splitext(filename)
                if not ext:
                    continue
                # Build full path
                full_path = os.path.join(root, filename)
                # Use the basename of the XML file as grouping key
                # if an XML file exists for this basename we group all files with this base
                package_files.setdefault(base_name, []).append(full_path)
    except Exception as e:
        raise RuntimeError(f"Error exploring folder '{folder}': {e}")

    # Filter out groups that have no XML file - only keep packages defined by XML
    return {
        key: vals
        for key, vals in package_files.items()
        if any(os.path.splitext(f)[1].lower() == ".xml" for f in vals)
    }

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string path, got {type(folder).__name__}")

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder not found: {folder}")

    # List all files in the directory
    try:
        entries = os.listdir(folder)
    except Exception as e:
        raise OSError(f"Error accessing directory '{folder}': {e}") from e

    files = [f for f in entries if os.path.isfile(os.path.join(folder, f))]

    packages = {}
    # First pass: find xml files and create package entries
    for fname in files:
        base, ext = os.path.splitext(fname)
        if ext.lower() == ".xml":
            xml_path = os.path.join(folder, fname)
            packages[base] = {"xml": xml_path, "files": [xml_path]}

    # Second pass: attach non-xml files to existing packages
    for fname in files:
        base, ext = os.path.splitext(fname)
        if base in packages and ext.lower() != ".xml":
            packages[base]["files"].append(os.path.join(folder, fname))

    return packages

