def add_asset(self, basename, file_path):
        """
        Add an asset with the specified basename and file path to the repository.
        Returns the newly created asset's ID.

        Raises:
            FileNotFoundError: If the provided file path does not exist.
            ValueError: If the asset form could not be obtained or asset creation fails.
        """
        # Verify the file exists
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        # Read file data and determine MIME type
        try:
            with open(file_path, 'rb') as f:
                file_bytes = f.read()
            mime_type, _ = mimetypes.guess_type(file_path)
        except Exception as exc:
            raise ValueError(f"Could not read file '{file_path}': {exc}") from exc

        # Obtain the repository provider manager
        try:
            repo_mgr = self._get_provider_manager('REPOSITORY')
        except Exception as exc:
            raise ValueError(f"Failed to obtain REPOSITORY provider manager: {exc}") from exc

        # Prepare the asset creation form
        try:
            asset_form = repo_mgr.get_asset_form_for_create([])
            asset_form.set_name(basename)
            if hasattr(asset_form, 'set_data'):
                asset_form.set_data(file_bytes)
            if hasattr(asset_form, 'set_mime_type') and mime_type:
                asset_form.set_mime_type(mime_type)
        except Exception as exc:
            raise ValueError(f"Failed to configure asset form: {exc}") from exc

        # Create the asset
        try:
            asset = repo_mgr.create_asset(asset_form)
            return asset.get_id()
        except Exception as exc:
            raise ValueError(f"Asset creation failed: {exc}") from exc

