def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    packages = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                # Skip directories
                if zinfo.is_dir():
                    continue

                filename = zinfo.filename
                # Normalize path: use forward slash as zip separator
                norm_path = filename.replace("\\", "/")
                basename = os.path.basename(norm_path)
                base, ext = os.path.splitext(basename)
                # Read file content
                try:
                    data = zin.read(zinfo)
                except Exception:
                    # Skip problematic file
                    continue

                if base not in packages:
                    packages[base] = {'xml': None, 'files': []}

                if ext.lower() == '.xml':
                    try:
                        packages[base]['xml'] = data.decode('utf-8')
                    except Exception:
                        packages[base]['xml'] = data
                else:
                    packages[base]['files'].append((norm_path, data))
    except (FileNotFoundError, zipfile.BadZipFile) as exc:
        raise RuntimeError(f"Cannot open zip file '{zip_path}': {exc}") from exc

    return packages

