            # Collect files by base name (i.e., name without extension)
            files_by_base = {}
            for entry in zf.infolist():
                if entry.is_dir():
                    continue  # ignore directories
                basename_no_ext = os.path.splitext(os.path.basename(entry.filename))[0]
                files_by_base.setdefault(basename_no_ext, []).append(entry.filename)

            # Filter to bases that have an XML descriptor
            for base, file_list in files_by_base.items():
                # Check if an XML file exists for this base
                has_xml = any(f.lower().endswith('.xml') and os.path.basename(f).lower() == f"{base}.xml"
                              for f in file_list)
                if not has_xml:
                    continue

                # Read all files belonging to this package
                pkg_contents = {}
                for fname in file_list:
                    with zf.open(fname) as fobj:
                        pkg_contents[fname] = fobj.read()
                package_data[base] = pkg_contents

    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Bad zip file {zip_path}: {e}") from e
    except Exception as e:
        # Re-raise with context
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

    return package_data

