                if not has_xml:
                    continue

                # Read all files belonging to this package
                pkg_contents = {}
                for fname in file_list:
                    with zf.open(fname) as fobj:
                        pkg_contents[fname] = fobj.read()
                package_data[base] = pkg_contents

    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Bad zip file {zip_path}: {e}") from e
    except Exception as e:
        # Re-raise with context
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

    return package_data

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path.

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for info in zf.infolist():
                if info.is_dir():
                    continue
                # Full file path inside the zip
                full_path = info.filename
                # Get the base name (e.g., 'foo.xml' from 'dir/foo.xml')
                base = os.path.basename(full_path)
                # Split into stem and extension
                stem, ext = os.path.splitext(base)
                if not stem:
                    continue
                ext_key = ext[1:].lower() if ext else ''
                # Read file contents as bytes
                try:
                    data = zf.read(info)
                except Exception:
                    # Skip file if reading fails
                    continue
                if stem not in result:
                    result[stem] = {}
                result[stem][ext_key] = data
    except (FileNotFoundError, zipfile.BadZipFile, PermissionError):
        # Return empty dict on error or log if needed
        return {}
    return result

