def render(pieces, style):
    """Render the given version pieces into the requested style."""
    try:
        # Validate pieces argument
        if not isinstance(pieces, (list, tuple)):
            raise TypeError("pieces must be a list or tuple of version components")
        if not pieces:
            raise ValueError("pieces must not be empty")

        # Convert each component to a string or keep None
        formatted = []
        for comp in pieces:
            if comp is None:
                formatted.append(None)
            elif isinstance(comp, (int, float)):
                formatted.append(str(comp))
            elif isinstance(comp, str):
                formatted.append(comp)
            else:
                raise TypeError(f"unsupported component type: {type(comp)}")

        # Normalise style
        if isinstance(style, str):
            style = style.lower()
        else:
            style = "simple"

        # Render according to style
        if style == "simple":
            # Join non-None components with a dot
            return ".".join([c for c in formatted if c is not None])

        elif style == "padded":
            # Pad numeric components to two digits
            padded = []
            for c in formatted:
                if c is None:
                    continue
                if c.isdigit():
                    padded.append(c.zfill(2))
                else:
                    padded.append(c)
            return ".".join(padded)

        elif style == "serial":
            # Concatenate all components with no separator
            return "".join([c for c in formatted if c is not None])

        elif style == "semantic":
            # Produce a semver string: MAJOR.MINOR.PATCH[-QUALIFIER]
