    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Validate input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    # Load the root inventory
    root_inv_path = os.path.join(self.root_path, "inventory.json")
    if not os.path.isfile(root_inv_path):
        raise ValueError(f"Root inventory file not found at {root_inv_path}")
    try:
        with open(root_inv_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to load root inventory: {exc}")
    if not isinstance(root_inventory, dict):
        raise ValueError("Root inventory must be a JSON object mapping items to digests")
    # Record differing digests
    self.different_digests = {}
    for dir_name in version_dirs:
        dir_path = os.path.join(self.root_path, dir_name)
        inv_path = os.path.join(dir_path, "inventory.json")
        if not os.path.isfile(inv_path):
            raise ValueError(f"Missing inventory file in version directory '{dir_name}'")
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inventory = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory from '{dir_name}': {exc}")
        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory in '{dir_name}' must be a JSON object")
        # Compare digests for items present in both inventories
        for key, root_digest in root_inventory.items():
            if key in inventory:
                inv_digest = inventory[key]
                if inv_digest != root_digest:
                    self.different_digests.setdefault(key, []).append(
                        (dir_name, inv_digest)
                    )
    return self.different_digests

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a root inventory to compare against
    if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
        raise AttributeError("object must have a 'root_inventory' dict attribute")
    root_inv = self.root_inventory

    # A mapping: file -> list of (version, digest) pairs where digest differs from root
    self.different_digests = {}

    for idx, dir_name in enumerate(version_dirs, start=1):
        inventory_path = os.path.join(dir_name, "inventory.json")
        try:
            with open(inventory_path, "r", encoding="utf-8") as fh:
                inv_data = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Could not load inventory for version directory '{dir_name}': {exc}")

        if not isinstance(inv_data, dict) or "entries" not in inv_data or not isinstance(inv_data["entries"], dict):
            raise ValueError(f"Inventory file '{inventory_path}' has an unexpected format")

        entries = inv_data["entries"]

        # Each inventory must list at least every item that exists in the root inventory
        missing_keys = [key for key in root_inv if key not in entries]
        if missing_keys:
            raise ValueError(
                f"Inventory for version '{dir_name}' is missing entries for keys: {missing_keys}"
            )

        # Record any differing digests compared to the root inventory
        for key, digest in entries.items():
            root_digest = root_inv.get(key)
            if root_digest is None or root_digest != digest:
                self.different_digests.setdefault(key, []).append((dir_name, digest))
    return self.different_digests if self.different_digests else None

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    if not version_dirs:
        raise ValueError("No version directories provided")

    # Initialize mapping for differences
    self.content_differences = {}

    # Load root inventory
    root_dir = version_dirs[0]
    root_inv_path = os.path.join(root_dir, "inventory.json")
    try:
        with open(root_inv_path, "r", encoding="utf-8") as fp:
            root_inventory = json.load(fp)
    except Exception as exc:
        raise ValueError(f"Failed to load root inventory from {root_inv_path}: {exc}")

    previous_inventory = root_inventory

    for ver in version_dirs:
        inv_path = os.path.join(ver, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory for version '{ver}': {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as fp:
                curr_inventory = json.load(fp)
        except Exception as exc:
            raise ValueError(f"Unable to parse inventory at {inv_path}: {exc}")

        # Ensure inventory consistency
        missing_keys = set(previous_inventory.keys()) - set(curr_inventory.keys())
        if missing_keys:
            raise ValueError(
                f"Inventory for version '{ver}' is missing entries: {sorted(missing_keys)}"
            )

        # Record digests that differ from the intent inventory
        diffs = []
        for key, prev_val in previous_inventory.items():
            curr_val = curr_inventory.get(key)
            if curr_val is None:
                continue
            if curr_val != prev_val:
                diffs.append((key, prev_val, curr_val))

        if diffs:
            self.content_differences.setdefault(ver, []).extend(diffs)

        previous_inventory = curr_inventory

    return self

