def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not bug_ids:
        # nothing to amend
        return params
    # Normalize bug_ids to a list of strings
    if isinstance(bug_ids, (int, str)):
        bug_ids_list = [str(bug_ids)]
    else:
        try:
            bug_ids_list = [str(bid) for bid in bug_ids]
        except Exception as exc:
            raise TypeError("bug_ids must be an iterable of ints or strings") from exc
    # Merge with existing 'ids' parameter if present
    existing_ids = params.get("ids")
    if existing_ids:
        try:
            existing_set = set(existing_ids.split(","))
        except Exception:
            existing_set = set()
    else:
        existing_set = set()
    merged_set = existing_set.union(bug_ids_list)
    # Sort for consistency
    merged_list = sorted(merged_set, key=lambda x: int(x) if x.isdigit() else x)
    params["ids"] = ",".join(merged_list)
    return params

def amend_bzparams(self, params, bug_ids):
    """
    Amend the Bugzilla params by adding bug IDs to the parameters dictionary.
    Accepts a dictionary of existing parameters and one or more bug IDs
    (int, str, list or tuple). The IDs are added under the 'id' key,
    preserving any existing values.
    """
    # Validate `params`
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    # Normalize single id into a list
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    # Validate `bug_ids`
    if not isinstance(bug_ids, (list, tuple)):
        raise TypeError("bug_ids must be an int, str, list, or tuple")
    for bid in bug_ids:
        if not isinstance(bid, (int, str)):
            raise TypeError("each bug ID must be an int or str")
    # Merge IDs into params
    if 'id' in params:
        existing = params['id']
        if isinstance(existing, list):
            params['id'] = existing + list(bug_ids)
        else:
            params['id'] = [existing] + list(bug_ids)
    else:
        params['id'] = list(bug_ids)

