def deep_merge_nodes(nodes):
    '''Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge two values
    def merge_values(val1, val2):
        # Skip if val1 is None (no prior value)
        if val1 is None:
            return val2
        # Both are MappingNode: deep merge
        try:
            is_mapping = lambda v: hasattr(v, 'tag') and v.tag == 'tag:yaml.org,2002:map'
        except Exception:
            is_mapping = lambda v: False
        if is_mapping(val1) and is_mapping(val2):
            return merge_mapping_nodes(val1, val2)
        # If val1 is MappingNode but val2 not, override
        if is_mapping(val1) and not is_mapping(val2):
            return val2
        # If val2 is MappingNode but val1 not, keep val2
        if not is_mapping(val1) and is_mapping(val2):
            return val2
        # Otherwise, simply take val2
        return val2

    # Helper to merge two MappingNodes
    def merge_mapping_nodes(map1, map2):
        # map1 and map2 are MappingNode objects
        # Build lookup of existing key values to index
        key_to_index = {}
        for idx, (key_node, _) in enumerate(map1.value):
            key_to_index[key_node.value] = idx
        # Iterate through map2 pairs
        for key_node2, val2 in map2.value:
            idx = key_to_index.get(key_node2.value)
            if idx is not None:
                # Existing key, merge values
                _, existing_val = map1.value[idx]
                merged_val = merge_values(existing_val, val2)
                map1.value[idx] = (key_node2, merged_val)
            else:
                # New key, append
                map1.value.append((key_node2, val2))
        return map1

    result = []
    key_to_index = {}
    for key_node, value_node in nodes:
        if not hasattr(key_node, 'value'):
            raise TypeError('Expected scalar key node with a value attribute')
        key_str = key_node.value
        if key_str in key_to_index:
            idx = key_to_index[key_str]
            _, current_val = result[idx]
            merged_val = merge_values(current_val, value_node)
            # Preserve the original key node from first occurrence
            result[idx] = (result[idx][0], merged_val)
        else:
            result.append((key_node, value_node))
            key_to_index[key_str] = len(result) - 1
    return result

def deep_merge_nodes(nodes):
    '''Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    Example use is shown in the docstring.'''
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (key, value) tuples')
    # Helper to detect MappingNode by tag suffix
    def _is_mapping(node):
        return hasattr(node, 'tag') and node.tag.endswith(':map')
    # Recursive merge of MappingNodes
    def _merge_mapping_nodes(map_a, map_b):
        a_items = list(map_a.value) if hasattr(map_a, 'value') else []
        b_items = list(map_b.value) if hasattr(map_b, 'value') else []
        merged = {}
        order = []
        for k, v in a_items:
            key_str = k.value if hasattr(k, 'value') else None
            merged[key_str] = (k, v)
            order.append(key_str)
        for k, v in b_items:
            key_str = k.value if hasattr(k, 'value') else None
            if key_str in merged:
                existing_k, existing_v = merged[key_str]
                if _is_mapping(existing_v) and _is_mapping(v):
                    merged_node = _merge_mapping_nodes(existing_v, v)
                    merged[key_str] = (existing_k, merged_node)
                else:
                    merged[key_str] = (existing_k, v)
            else:
                merged[key_str] = (k, v)
                order.append(key_str)
        # Build new value list
        new_value = [merged[k] for k in order]
        map_a.value = new_value
        return map_a
    seen = {}
    key_order = []
    for key_node, val_node in nodes:
        if not hasattr(key_node, 'value'):
            raise ValueError('Key node lacks a value attribute')
        key_str = key_node.value
        if key_str in seen:
            existing_val = seen[key_str][1]
            if _is_mapping(existing_val) and _is_mapping(val_node):
                merged = _merge_mapping_nodes(existing_val, val_node)
                seen[key_str] = (seen[key_str][0], merged)
            else:
                # last wins
                seen[key_str] = (seen[key_str][0], val_node)
        else:
            seen[key_str] = (key_node, val_node)
            key_order.append(key_str)
    result = [(seen[k][0], seen[k][1]) for k in key_order]
    return result

