def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed
    namespace of arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Ensure unparsed_arguments is a list; allow any iterable
    if not isinstance(unparsed_arguments, (list, tuple)):
        try:
            unparsed_arguments = list(unparsed_arguments)
        except Exception as exc:
            raise TypeError("unparsed_arguments must be an iterable of strings") from exc

    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a mapping from name to ArgumentParser")

    parsed = {}
    remaining_sets = []

    for name, parser in subparsers.items():
        if not hasattr(parser, "parse_known_args"):
            raise TypeError(f"Object for subparser '{name}' is not an ArgumentParser")
        try:
            ns, remaining = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            raise RuntimeError(f"Error parsing arguments for subparser '{name}': {exc}") from exc
        parsed[name] = ns
        remaining_sets.append(set(remaining))

    if remaining_sets:
        # Arguments not claimed by any subparser
        common_remaining = set.intersection(*remaining_sets)
        remaining_args = [arg for arg in unparsed_arguments if arg in common_remaining]
    else:
        # No subparsers to parse against, everything is remaining
        remaining_args = list(unparsed_arguments)

    return parsed, remaining_args

