def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise ValueError("size must be a string")
    size = size.strip()
    if not size:
        raise ValueError("size string is empty")
    # Split numeric part and unit part
    numeric_part = ''
    unit_part = ''
    for idx, char in enumerate(size):
        if char.isdigit() or char in '.,':
            # keep dot and comma as decimal separators
            numeric_part += char
        else:
            unit_part = size[idx:].strip()
            break
    if numeric_part == '':
        raise ValueError(f"no numeric value found in '{size}'")
    # Replace comma with dot if present
    numeric_part = numeric_part.replace(',', '.')
    try:
        value = float(numeric_part)
    except ValueError:
        raise ValueError(f"invalid numeric value '{numeric_part}' in '{size}'")
    if value < 0:
        raise ValueError("size cannot be negative")
    unit_part = unit_part.upper()
    if unit_part in ('', 'B'):
        exponent = 0
    elif unit_part in ('K', 'KB'):
        exponent = 1
    elif unit_part in ('M', 'MB'):
        exponent = 2
    elif unit_part in ('G', 'GB'):
        exponent = 3
    elif unit_part in ('T', 'TB'):
        exponent = 4
    elif unit_part in ('P', 'PB'):
        exponent = 5
    elif unit_part in ('E', 'EB'):
        exponent = 6
    elif unit_part in ('Z', 'ZB'):
        exponent = 7
    elif unit_part in ('Y', 'YB'):
        exponent = 8
    else:
        raise ValueError(f"unknown unit '{unit_part}' in '{size}'")
    bytes_value = int(round(value * (1000 ** exponent)))
    return bytes_value

