def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    # Ensure we have an iterable; if None, treat as empty
    if dicts is None:
        return result
    for d in dicts:
        # Skip non-dict entries silently
        if not isinstance(d, dict):
            continue
        for key, value in d.items():
            if key in result:
                try:
                    # Attempt to sum numeric values
                    result[key] += value
                except Exception:
                    # If addition fails (e.g., non-numeric), override with the new value
                    result[key] = value
            else:
                result[key] = value
    return result

