def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Validate the input types
    if not isinstance(url, str):
        raise TypeError("url must be a string")

    # Allow any mapping‑like object (dict, OrderedDict, etc.)
    try:
        iter(url_args)
    except TypeError:
        raise TypeError("url_args must be a mapping of keys to values")

    # If there are no arguments, nothing to replace
    if not url_args:
        return url

    # Regular expression to find placeholders like {key}
    placeholder_regex = re.compile(r'\{([^{}]+)\}')

    def _replace(match):
        key = match.group(1)
        if key not in url_args:
            # A missing key is considered an error – the caller needs to supply
            # all placeholders that appear in the URL.
            raise KeyError(
                f"URL argument '{key}' not provided for replacement."
            )
        value = url_args[key]
        # None is treated as an empty string
        if value is None:
            value = ''
        # Convert to string – this also handles numeric types
        return str(value)

    # Perform the substitution
    return placeholder_regex.sub(_replace, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not url_args:
        return url

    # Find placeholders like {key} and replace with corresponding value.
    # If key not found, leave placeholder unchanged.
    pattern = re.compile(r'\{([^{}]+)\}')

    def replace(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)

    return pattern.sub(replace, url)

