def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string."""
    # Validate that parser has the attributes we expect from argparse.ArgumentParser
    if parser is None or not hasattr(parser, "_actions"):
        raise ValueError("Expected an argparse.ArgumentParser instance, got {0}".format(type(parser).__name__))

    flags = []
    try:
        for action in parser._actions:
            # action.option_strings is a list of flag strings (e.g., ['-v', '--verbose'])
            if getattr(action, "option_strings", None):
                flags.extend(action.option_strings)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc

    return ' '.join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
