    # is not an ArgumentParser or does not expose the expected interface.
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError("Expected an argparse.ArgumentParser instance")

    flags = []
    for action in actions:
        # Positional arguments have an empty list of option_strings, which we skip.
        option_strings = getattr(action, 'option_strings', [])
        for flag in option_strings:
            if isinstance(flag, str) and flag:
                flags.append(flag)

    return ' '.join(flags)

