def vertex3tuple(vertices):
    '''
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    '''
    try:
        verts = list(vertices)
    except Exception:
        raise TypeError('vertices must be an iterable of points')
    n = len(verts)
    if n == 0:
        return []
    if n < 3:
        # Not enough vertices to form triples; return copies of existing vertices
        return [tuple(verts)] * n
    result = []
    for i in range(n):
        result.append((verts[i-1], verts[i], verts[(i+1) % n]))
    return result

