def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("alphabet must be a list of at least two characters")
    base = len(alphabet)
    try:
        pad = int(padding) if padding is not None else None
    except Exception:
        raise TypeError("padding must be an integer or None")
    if pad is not None and pad < 0:
        raise ValueError("padding must be non-negative")
    # Handle zero explicitly
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))
    if pad is not None and len(result) < pad:
        pad_char = alphabet[0]
        result = pad_char * (pad - len(result)) + result
    return result

