    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters for a valid radix")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Handle sign
    sign = ''
    if number < 0:
        sign = '-'
        number = -number

    # Convert number to digits in reverse order
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        digits.reverse()

    result = sign + ''.join(digits)

    # Apply padding if requested
    if padding is not None and len(result.lstrip('-')) < padding:
        pad_len = padding - len(result.lstrip('-'))
        pad_str = alphabet[0] * pad_len
        if sign:
            # insert padding after the sign
            result = sign + pad_str + result[1:]
        else:
            result = pad_str + result

    return result

