def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic type validation
    if not isinstance(string, str):
        raise TypeError(f"string must be a str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"alphabet must be a list, got {type(alphabet).__name__}")

    # Alphabet must not be empty and must contain unique single‑character strings
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    seen = set()
    for ch in alphabet:
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"alphabet elements must be single‑character strings, got {ch!r}")
        if ch in seen:
            raise ValueError(f"duplicate character in alphabet: {ch!r}")
        seen.add(ch)

    base = len(alphabet)
    # Pre‑compute mapping from character to its numeric value
    char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}

    if string == "":
        raise ValueError("string cannot be empty")

    result = 0
    for c in string:
        if c not in char_to_value:
            raise ValueError(f"character {c!r} not found in alphabet")
        result = result * base + char_to_value[c]
    return result

