def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    import tempfile
    import tarfile
    from pathlib import Path

    # Validate input types
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        destination_path = Path(destination_path)

    # Ensure destination_path is a directory
    if destination_path.exists():
        if not destination_path.is_dir():
            raise ValueError(f"Destination path {destination_path!s} exists and is not a directory")
        # Check for existing contents; the extraction expects an empty directory
        if any(destination_path.iterdir()):
            raise RuntimeError(f"Destination directory {destination_path!s} is not empty")
    else:
        try:
            destination_path.mkdir(parents=True, exist_ok=True)
        except Exception as err:
            raise RuntimeError(f"Could not create destination directory {destination_path!s}: {err}")

    # Download the archive to a temporary file
    tmp_file = None
    try:
        tmp_file = tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz")
        try:
            with requests.get(url, stream=True, timeout=30) as resp:
                resp.raise_for_status()
                for chunk in resp.iter_content(chunk_size=8192):
                    if chunk:
                        tmp_file.write(chunk)
        finally:
            tmp_file.close()

        # Extract the archive
        try:
            with tarfile.open(tmp_file.name, mode="r:gz") as tar:
                tar.extractall(path=str(destination_path))
        except tarfile.ReadError as exc:
            raise RuntimeError(f"Failed to read tar archive from {url!s}: {exc}")

    except Exception as exc:
        raise RuntimeError(f"Error while retrieving or extracting repository archive: {exc}") from exc
    finally:
        # Clean up the temporary file
        if tmp_file is not None:
            try:
                Path(tmp_file.name).unlink(missing_ok=True)
            except Exception:
                pass

    return destination_path

