def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    def _to_regex(pattern):
        if not isinstance(pattern, str):
            return pattern
        # Convert Unix-style wildcard pattern to a regex pattern.
        # Escape all regex meta characters except * and ?.
        regex = '^'
        for ch in pattern:
            if ch == '*':
                regex += '.*'
            elif ch == '?':
                regex += '.'
            else:
                regex += re.escape(ch)
        regex += '$'
        return regex

    if not isinstance(item, dict):
        raise TypeError("regex_dict expects a dict")
    result = {}
    for k, v in item.items():
        try:
            new_key = _to_regex(k)
        except Exception:
            new_key = k
        result[new_key] = v
    return result

