        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError(f"Expected a dict, got {type(item).__name__}")
    try:
        result = {}
        for key, value in item.items():
            if isinstance(key, str) and ('*' in key or '?' in key):
                # Escape regex metacharacters except for wildcard placeholders
                pattern = re.escape(key)
                # Replace glob wildcards with regex equivalents
                pattern = pattern.replace(r'\*', '.*').replace(r'\?', '.')
                # Anchor the pattern to match the whole string
                pattern = f'^{pattern}$'
                result[pattern] = value
            else:
                result[key] = value
        return result
    except Exception as exc:
        raise RuntimeError(f"Failed to convert dict keys to regexes: {exc}") from exc

