def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if len(name) < 2:
        return name
    if name[0] == name[-1] and name[0] in ('"', "'"):
        return name[1:-1]
    return name

def unquote(name):
    """Remove quote from the given name."""
    # Guard against non-string input
    if not isinstance(name, str):
        return name

    # Strip matching single or double quotes from the entire string
    m = re.match(r'^(["\'])(.*)\1$', name)
    if m:
        return m.group(2)

    # Strip angle brackets if used as quotation marks
    m = re.match(r'^<(.+?)>$', name)
    if m:
        return m.group(1)

    # Return the original string if no surrounding quotes are found
    return name

