def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    # Explicit check for the common hostname
    if isinstance(host, str) and host.lower() == "localhost":
        return True

    try:
        # Resolve the host to all address info
        infos = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except (socket.gaierror, TypeError):
        # If the host cannot be resolved or is invalid
        return False

    for family, _, _, _, sockaddr in infos:
        ip = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4 loopback addresses are 127.0.0.0/8
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback address is ::1
            # Normalize the address to remove zone identifiers for comparison
            if ip.split("%")[0] == "::1":
                return True

    return False

