            # IPv4 with port
            host_ip = host_clean.split(":")[0]
        else:
            host_ip = host_clean
    except Exception:
        host_ip = host_clean

    try:
        # Use getaddrinfo to resolve host; port is irrelevant here, use 0
        infos = socket.getaddrinfo(host_ip, 0, 0, 0, socket.IPPROTO_TCP)
    except socket.gaierror:
        return False

    for result in infos:
        family, _, _, _, sockaddr = result
        if family == socket.AF_INET:
            addr = sockaddr[0]
            if addr == "127.0.0.1":
                return True
        elif family == socket.AF_INET6:
            addr = sockaddr[0]
            # IPv6 canonical loopback forms
            if addr in ("::1", "0:0:0:0:0:0:0:1", "::"):
                return True
    return False

