def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    # Expand user tilde (~) in the path
    config_filename = os.path.expanduser(config_filename)

    # If the file exists and overwrite is not requested, do nothing
    if os.path.isfile(config_filename) and not overwrite:
        return

    # Ensure the destination directory exists
    dir_name = os.path.dirname(config_filename)
    if dir_name:
        try:
            os.makedirs(dir_name, exist_ok=True)
        except OSError:
            # Raise if the directory still does not exist after attempting to create it
            if not os.path.isdir(dir_name):
                raise

    # Prepare the content to write
    if isinstance(rendered_config, str):
        content = rendered_config
    else:
        # Assume rendered_config is a Python object that can be serialized to YAML
        try:
            import yaml
            content = yaml.safe_dump(rendered_config, default_flow_style=False)
        except Exception as exc:
            raise ValueError("Failed to serialize rendered_config to YAML") from exc

    # Write content to the file
    try:
        with open(config_filename, 'w') as f:
            f.write(content)
        # Apply the requested file permissions
        os.chmod(config_filename, mode)
    except OSError as exc:
        raise OSError(f"Failed to write configuration file '{config_filename}': {exc}") from exc
    return True

