def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine the variable name and default value from various matcher forms
    if isinstance(matcher, (list, tuple)):
        # Accept positional form: (name,) or (name, default)
        if not matcher:
            raise ValueError("Matcher tuple/list must contain at least the variable name.")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    elif isinstance(matcher, dict):
        # Accept dict with 'name' and optional 'default'
        if 'name' not in matcher:
            raise KeyError("The matcher dict must contain a 'name' key.")
        name = matcher['name']
        default = matcher.get('default')
    elif isinstance(matcher, str):
        # Simple string: just the variable name
        name = matcher
        default = None
    else:
        # Attempt attribute access (e.g., an object with .name and .default)
        try:
            name = matcher.name
        except AttributeError:
            raise TypeError("Matcher must be a string, tuple/list, dict, or object with a 'name' attribute.")
        default = getattr(matcher, 'default', None)

    # Retrieve the environment variable
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise EnvironmentError(f"Environment variable '{name}' not found and no default provided.")
    return value

