def build_app_logger(name='app', logfile='app.log', debug=True):
    """
    General purpose application logger. Useful mainly for debugging
    """
    logger = logging.getLogger(name)
    logger.setLevel(logging.DEBUG if debug else logging.INFO)

    formatter = logging.Formatter(
        '%(asctime)s [%(levelname)s] %(name)s: %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )

    # Console handler
    try:
        import sys
        console_handler = logging.StreamHandler(sys.stdout)
        console_handler.setLevel(logger.level)
        console_handler.setFormatter(formatter)
        if not any(
            isinstance(h, logging.StreamHandler) for h in logger.handlers
        ):
            logger.addHandler(console_handler)
    except Exception:
        pass  # ignore console issues

    # File handler
    if logfile:
        try:
            log_dir = os.path.dirname(os.path.abspath(logfile))
            if log_dir:
                os.makedirs(log_dir, exist_ok=True)
            file_handler = logging.FileHandler(logfile)
            file_handler.setLevel(logger.level)
            file_handler.setFormatter(formatter)
            if not any(
                isinstance(h, logging.FileHandler) and getattr(h, 'baseFilename', None) == os.path.abspath(logfile)
                for h in logger.handlers
            ):
                logger.addHandler(file_handler)
        except Exception:
            pass  # skip file handler if it cannot be created

    return logger

