def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mean = 0.2
    sigma = 0.1
    if sigma <= 0:
        raise ValueError("Sigma must be positive.")
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input must be array-like numbers.") from e

    # Compute the normal PDF
    prefactor = 1.0 / (sigma * np.sqrt(2 * np.pi))
    exponent = -0.5 * ((arr - mean) / sigma) ** 2
    return prefactor * np.exp(exponent)

