def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Handle None explicitly
    if seq is None:
        return None, None

    # Strings and bytes are already sequences that support indexing
    if isinstance(seq, (str, bytes)):
        return seq, type(seq)

    # If seq supports both __len__ and __getitem__, assume it's a random‑access sequence
    if hasattr(seq, "__len__") and hasattr(seq, "__getitem__"):
        return seq, type(seq)

    # For other iterables (generators, iter(), etc.), convert to a list
    try:
        seq_list = list(seq)
    except Exception as exc:
        raise TypeError(f"Argument seq must be an iterable or sequence, got {type(seq).__name__}") from exc

    return seq_list, list

