    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Known sequence types that we can return as-is
    if isinstance(seq, (list, tuple, str, bytes)):
        return seq, type(seq)

    # If seq is not a built‑in sequence, try to consume it
    if seq is None:
        raise TypeError("None is not a valid sequence or iterable")

    # Handle iterable objects (generators, file objects, iterators, etc.)
    try:
        if bufsize is None:
            derived = list(seq)
        else:
            import itertools
            derived = list(itertools.islice(seq, bufsize))
    except TypeError as exc:
        # seq is not iterable
        raise TypeError(f"'{seq!r}' is not a valid sequence or iterable") from exc

    return derived, type(seq)

