    # Handle None explicitly
    if seq is None:
        return (None, None)

    # Strings and bytes are already contiguous sequences
    if isinstance(seq, (str, bytes, bytearray)):
        t = "string" if isinstance(seq, str) else ("bytes" if isinstance(seq, bytes) else "bytearray")
        return (seq, t)

    # Built-in sequence types that we can return unchanged
    if isinstance(seq, (list, tuple, set, range)):
        return (seq, seq.__class__.__name__)

    # Dictionary: keep as is, record type
    if isinstance(seq, dict):
        return (seq, "dict")

