def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Build list of candidate metaclasses
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(
                f"__metaclass__ must be a class, not {type(explicit_mc).__name__}"
            )
        metaclasses = [explicit_mc]
    else:
        metaclasses = [type(b) for b in bases]

    # Remove duplicates while preserving order
    seen = []
    for m in metaclasses:
        if m not in seen:
            seen.append(m)

    # Default metaclass if none were provided
    if not seen:
        return type

    # Resolve the most derived metaclass
    chosen = seen[0]
    for m in seen[1:]:
        try:
            if issubclass(chosen, m):
                chosen = m
            elif not issubclass(m, chosen):
                raise TypeError(
                    f"metaclass conflict: {chosen.__name__} vs {m.__name__}"
                )
        except TypeError as exc:
            # Raised if chosen or m is not a class
            raise TypeError(
                f"invalid metaclass: {chosen} or {m} is not a class"
            ) from exc

    return chosen

