        mc = explicit_mc
    else:
        # No explicit metaclass: derive from the bases' metaclasses.
        # All bases must be classes; otherwise, fallback to 'type'.
        metaclasses = []
        for base in bases:
            try:
                metaclasses.append(type(base))
            except TypeError:
                # Non-class base; ignore it
                pass
        if not metaclasses:
            mc = type
        else:
            # Find a common metaclass: the most derived of all encountered metaclasses.
            mc = metaclasses[0]
            for candidate in metaclasses[1:]:
                if issubclass(candidate, mc):
                    mc = candidate
                elif not issubclass(mc, candidate):
                    # No common metaclass exists.
                    raise TypeError(
