    for m in reversed(metas):
        if all(issubclass(m, other) for other in metas):
            return m

    # If no common metaclass can be determined, raise an informative error
    base_names = ", ".join(f"{b.__name__}" for b in bases)
    raise TypeError(
        f"Cannot find a common metaclass for bases: {base_names}"
    )

