def fromutc(self, dt):
        """Given a timezone-aware datetime in a given timezone, calculates a
        timezone-aware datetime in a new timezone.

        Since this is the one time that we *know* we have an unambiguous
        datetime object, we take this opportunity to determine whether the
        datetime is ambiguous and in a "fold" state (e.g. if it's the first
        occurrence, chronologically, of the ambiguous datetime).

        :param dt:
            A timezone-aware :class:`datetime.datetime` object.
        """
        if dt is None:
            raise TypeError("datetime argument is None")
        if not isinstance(dt, datetime.datetime):
            raise TypeError("dt must be a datetime.datetime instance")
        if dt.tzinfo is None:
            raise TypeError("dt must be timezone-aware")

        target_tz = getattr(self, "tz", None)
        if target_tz is None:
            raise AttributeError("The object does not have a 'tz' attribute for conversion")

        try:
            converted = dt.astimezone(target_tz)
        except Exception as exc:
            raise ValueError(f"Unable to convert datetime to target timezone: {exc}") from exc

        # Preserve fold information if present (Python 3.6+)
        if hasattr(dt, "fold"):
            try:
                converted = converted.replace(fold=dt.fold)
            except Exception:
                pass

        return converted

