def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    try:
        import datetime
    except Exception:
        return None  # datetime not available

    if dt is None:
        return None

    # If string, try to parse it, otherwise return as is
    if isinstance(dt, str):
        try:
            # Replace 'Z' with '+00:00' for parsing
            parsed = datetime.datetime.fromisoformat(dt.replace('Z', '+00:00'))
            dt = parsed
        except Exception:
            return dt

    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime.datetime instance or ISO datetime string")

    # Ensure timezone is UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)

    # Include microseconds only if present
    if dt.microsecond:
        fmt = "%Y-%m-%dT%H:%M:%S.%fZ"
    else:
        fmt = "%Y-%m-%dT%H:%M:%SZ"

    return dt.strftime(fmt)

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Ensure we are working with a datetime instance
    if not isinstance(dt, datetime.datetime):
        raise TypeError(f"log:format_dt expected datetime, got {type(dt).__name__}")

    # If no timezone info is present, assume UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)

    # Convert to UTC to match the expected D* node format
    dt_utc = dt.astimezone(datetime.timezone.utc)

    # Format according to ISO 8601 with trailing 'Z'
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")

