def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    if not isinstance(text, str):
        raise TypeError("Input must be a string")
    # Regular expression to find URLs (http(s):// or www.) and plain file-like paths
    url_re = re.compile(
        r'''(?x)
        (?:                 # Non-capturing group for the whole URL
          (?P<prefix>[^<>"'\s])?  # Optional preceding character that is not a link context
          (?P<url>
            (?:
              https?://          # http:// or https://
              |
              www\.
            )
            [^\s<>"']+          # The rest of the URL
          )
        )
        |
        (?P<path>
          (?:[A-Za-z]:)?      # Windows drive letter
          [\/\.\w.-]+          # Path characters
          \.\w+                # Extension
        )
        '''
    )
    def _repl(match):
        # If the match is a url, linkify it
        if match.group("url"):
            url = match.group("url")
            href = url
            if url.startswith("www."):
                href = "http://" + url
            prefix = match.group("prefix") or ""
            return f'{prefix}<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'
        # If the match is a file path, linkify it as a relative link
        if match.group("path"):
            path = match.group("path")
            return f'<a href="/browse/{path}">{path}</a>'
        return match.group(0)

    try:
        return url_re.sub(_repl, text)
    except Exception:
        # On any error, return the original text unmodified
        return text

