    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        # Import required cryptographic primitives
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding
        from cryptography.exceptions import InvalidSignature
        import base64

        # Normalise input data
        if isinstance(doc, bytes):
            doc_bytes = doc
        elif isinstance(doc, str):
            doc_bytes = doc.encode('utf-8')
        else:
            raise TypeError("doc must be a str or bytes")

        if isinstance(signature, str):
            sig_bytes = base64.b64decode(signature.strip())
        elif isinstance(signature, bytes):
            sig_bytes = signature
        else:
            raise TypeError("signature must be a str (base64) or bytes")

        # Load the public key
        if isinstance(public_key, (bytes, str)):
            # Assume PEM encoded key
            if isinstance(public_key, str):
                key_bytes = public_key.encode()
            else:
                key_bytes = public_key
            key = serialization.load_pem_public_key(key_bytes)
        else:
            # Assume already a key object
            key = public_key

        # Perform the verification using RSA PSS padding and SHA-256
        key.verify(
            sig_bytes,
            doc_bytes,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except (InvalidSignature, ValueError, TypeError, Exception):
        return False

