    except Exception:
        # Handle missing '@' or other split errors
        return None

    # Construct the resource parameter
    resource = "acct:" + handle
    try:
        # Use urllib.quote for URL‑encoding in a Python‑2 / Python‑3 compatible way
        try:
            from urllib import quote
        except Exception:
            from urllib.parse import quote
    except Exception:
        return None

    # Build the WebFinger URL
    url = "https://%s/.well-known/webfinger?resource=%s" % (host, quote(resource))

    # Attempt to fetch the document
    try:
