def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Validate handle and split into user@host
    try:
        # Only split at the first '@'
        _, host = handle.split("@", 1)
    except ValueError:
        # Handle is not of the form user@host
        return None

    # Ensure the host is non‑empty
    if not host:
        return None

    # Build the resource parameter (RFC7033 requires acct:user@host)
    resource_uri = f"acct:{handle}"
    try:
        import urllib.request, urllib.parse, urllib.error
        import xml.etree.ElementTree as ET
    except ImportError:
        # Required modules are unavailable
        return None

    # Helper to GET a URL and return its text or None on error
    def _fetch_text(url: str) -> Optional[str]:
        try:
            with urllib.request.urlopen(url, timeout=5) as resp:
                content_type = resp.info().get_content_charset()
                if not content_type:
                    content_type = "utf-8"
                return resp.read().decode(content_type, errors="ignore")
        except Exception:
            return None

    # 1. Try the standard /.well‑known/webfinger endpoint
    wf_url = f"https://{host}/.well-known/webfinger?resource={urllib.parse.quote(resource_uri)}"
    doc = _fetch_text(wf_url)
    if doc:
        return doc

    # 2. Fallback: retrieve host‑meta to find an LRDD entry
    hm_url = f"https://{host}/.well-known/host-meta"
    hm_doc = _fetch_text(hm_url)
    if not hm_doc:
        return None

    # Parse the host‑meta XML to locate the linked template
    try:
        root = ET.fromstring(hm_doc)
        # XPath style search: any Link element with rel='lrdd'
        for link in root.iter():
            if link.tag.endswith("Link") and link.attrib.get("rel") == "lrdd":
                template = link.attrib.get("template")
                if template:
                    lrdd_url = template.replace("{uri}", urllib.parse.quote(resource_uri))
                    lrdd_doc = _fetch_text(lrdd_url)
                    return lrdd_doc
                break
    except ET.ParseError:
        pass

