def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        if not isinstance(cli_args, dict):
            raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
        if not isinstance(answer_file_args, dict):
            raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

        # Identify arguments that appear in both the CLI and the answer file.
        duplicate_keys = set(cli_args.keys()) & set(answer_file_args.keys())
        if duplicate_keys:
            import warnings
            for key in sorted(duplicate_keys):
                warnings.warn(
                    f"Argument '{key}' is deprecated in the answer file and will "
                    "be ignored in favour of the value provided on the command line.",
                    category=DeprecationWarning,
                    stacklevel=2,
                )
            # Remove deprecated arguments from the answer file dictionary.
            cleaned_answer = {k: v for k, v in answer_file_args.items() if k not in duplicate_keys}
        else:
            cleaned_answer = dict(answer_file_args)

        return cleaned_answer

