        if not isinstance(attr, dict) or 'choices' not in attr:
            continue
        if arg_name not in args:
            continue
        value = args[arg_name]
        # If the value is iterable (but not a string/bytes), validate each element
        if isinstance(value, (list, tuple)):
            for val in value:
                if val not in attr['choices']:
                    raise ValueError(
