            arg_name, attrs = next(iter(arg_dict.items()))
            arg_defs[arg_name] = attrs

    # Validate each argument that has a 'choices' constraint.
    for arg_name, attrs in arg_defs.items():
        if "choices" not in attrs:
            continue
        allowed = attrs["choices"]
        if not isinstance(allowed, (list, set, tuple)):
            # If choices is not a collection, treat as a single allowed value.
            allowed = {allowed}
        else:
            allowed = set(allowed)

        if arg_name not in args:
