def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :return: args if all values are within the configured bounds.
    :raises ValueError: If the bounds are not set correctly or if an argument
        falls outside the allowed range.
    :raises TypeError: If the provided arguments are not a sequence or if a
        comparison cannot be performed.
    """
    # Ensure args is a sequence
    if args is None:
        raise ValueError("args cannot be None")
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")

    # Retrieve bounds from the instance
    min_value = getattr(self, "min_", None)
    max_value = getattr(self, "max_", None)

    if min_value is None and max_value is None:
        raise ValueError("Neither min_ nor max_ is defined on the instance")

    if min_value is not None and max_value is not None and min_value > max_value:
        raise ValueError("min_ cannot be greater than max_")

    for idx, val in enumerate(args):
        if val is None:
            continue  # skip None values

        # Attempt comparisons; raise informative error if not comparable
        try:
            if min_value is not None and val < min_value:
                raise ValueError(
                    f"argument at position {idx} (value={val}) is below minimum {min_value}"
                )
            if max_value is not None and val > max_value:
                raise ValueError(
                    f"argument at position {idx} (value={val}) exceeds maximum {max_value}"
                )
        except TypeError as exc:
            raise TypeError(
                f"cannot compare value {val} (type {type(val)}) with bounds"
            ) from exc

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable and convert to a list for repeated access
    try:
        args_list = list(args)
    except TypeError:
        raise TypeError("args must be an iterable of (value, min, max) tuples or lists")

    for idx, arg in enumerate(args_list):
        if not isinstance(arg, (list, tuple)):
