def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type.

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of arguments
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    # First try to use a factory provided in the specification
    factory = spec_option.get("factory")
    if factory is not None:
        if not callable(factory):
            raise TypeError("spec_option['factory'] must be callable")
        try:
            instance = factory(subcommand, type_name, option_name, spec_option)
            # Return whatever the factory produced; typically a callable or type
            return instance
        except Exception as exc:
            raise RuntimeError(
                f"Error creating complex argument type using factory: {exc}"
            ) from exc

    # If no factory, provide a reasonable default interpretation.
    # The default assumes a comma‑separated list of key=value pairs
    # and returns a dict.
    def _default_type(value: str):
        """Parse a string into a dictionary of key/value pairs."""
        result = {}
        if value:
            for part in value.split(","):
                part = part.strip()
                if not part:
                    continue
                if "=" in part:
                    key, val = part.split("=", 1)
                    result[key.strip()] = val.strip()
                else:
                    result[part] = True
        return result

    return _default_type

