    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    if args is None:
        return control_args, nested_args

    # Normalise args into mapping of key -> value
    # Accept dict, list of tuples, or list of '--key=value' strings
    parsed = {}
    if isinstance(args, dict):
        parsed = dict(args)
    else:
        # Assume it is an iterable of strings or tuples
        for item in args:
            if isinstance(item, dict):
                parsed.update(item)
            elif isinstance(item, (list, tuple)) and len(item) >= 2:
                parsed[item[0]] = item[1]
            elif isinstance(item, str):
                # Handle --key=value or key=value or --key value style
                if "=" in item:
                    key, val = item.split("=", 1)
                else:
                    # If standalone flag without value, set True
                    key, val = item, True
                # Strip leading dashes
                key = key.lstrip("-")
                parsed[key] = val

    # Define convention: keys starting with "ctl_" are control arguments
    # keys starting with "custom_" are custom ansible variables that go into nested
    # All other keys are considered nested arguments
    for key, val in parsed.items():
        stripped = key.lstrip("-")
        if stripped.startswith("ctl_"):
            control_args[stripped] = val
        elif stripped.startswith("custom_"):
            # Store under the variable name without custom_ prefix
            var_name = stripped[len("custom_"):]
            nested_args[var_name] = val
        else:
            nested_args[stripped] = val

    return control_args, nested_args

