def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Validate inputs
    if not isinstance(cli_args, list):
        raise TypeError(f"cli_args must be a list, got {type(cli_args).__name__}")
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

    # Compose the base command
    command = ["ansible-playbook"]
    command.extend(cli_args)

    # Serialize vars_dict to JSON for Ansible -e option
    if vars_dict:
        try:
            import json
            extra_vars = json.dumps(vars_dict, default=str)
            command.extend(["-e", extra_vars])
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Failed to serialize vars_dict to JSON: {exc}") from exc

    # Determine working directory from workspace if available
    cwd = None
    try:
        cwd = getattr(ir_workspace, "root", None) or getattr(ir_workspace, "path", None)
        if cwd is not None and not isinstance(cwd, str):
            cwd = None
    except Exception:
        cwd = None

    # Determine additional environment variables from plugin if available
    env = None
    try:
        if hasattr(ir_plugin, "env") and isinstance(ir_plugin.env, dict):
            env = {**os.environ, **ir_plugin.env}
    except Exception:
        env = None

    try:
        import subprocess
        proc = subprocess.run(
            command,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=True
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. "
                           "Please ensure Ansible is installed and in PATH.")
    except subprocess.CalledProcessError as exc:
        # Include stdout and stderr to aid troubleshooting
        output = (exc.stdout or "") + "\n" + (exc.stderr or "")
        raise RuntimeError(
            f"Ansible command failed with return code {exc.returncode}:\n{output}"
        ) from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error running ansible-playbook: {exc}") from exc

    return proc.stdout.strip() if proc.stdout is not None else ""

