def extend_cli(self, root_subparsers):
    """
    Adds the spec CLI options to the main entry point.

    :param root_subparsers: The subparser object(s) to extend.  It may be a
        collection of subparsers (e.g. a dict mapping command names to
        ArgumentParser instances, a list, or a single ArgumentParser).
    """
    # No operation if no subparsers were provided
    if root_subparsers is None:
        return

    # Normalise the collection into an iterable of parsers
    if isinstance(root_subparsers, dict):
        parsers = root_subparsers.values()
    elif hasattr(root_subparsers, "__iter__"):
        parsers = list(root_subparsers)
    else:
        # Assume a single parser
        parsers = (root_subparsers,)

    # Define common CLI options that should be added to each parser
    spec_option = {
        "args": ("--spec",),
        "kwargs": {
            "metavar": "SPEC",
            "help": ("Specify the target specification in the form "
                     "<path>:<name>. If omitted, the default target from the "
                     "current build file is used."),
        },
    }

    verbose_option = {
        "args": ("--verbose",),
        "kwargs": {
            "action": "store_true",
            "help": "Enable verbose output.",
        },
    }

    for parser in parsers:
        # Defensive check: ensure this is an ArgumentParser-like object
        if not hasattr(parser, "add_argument"):
            continue
        parser.add_argument(*spec_option["args"], **spec_option["kwargs"])
        parser.add_argument(*verbose_option["args"], **verbose_option["kwargs"])

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to the main entry point.

    :param subparser: the subparser object to extend.
    """
    # Normalise input: it might be an argparse._SubParsersAction or an iterable of subparsers
    try:
        # argparse.SubParsersAction has `choices` dict mapping names to subparsers
        subparsers = getattr(root_subparsers, "choices", None)
        if subparsers is None:
            # fall back to treating the argument as an iterable of subparsers
            subparsers = {f"#{i}": sp for i, sp in enumerate(root_subparsers)}
    except Exception as exc:
        raise TypeError(
            f"root_subparsers must be a SubParsersAction or an iterable of subparsers, got {root_subparsers!r} "
            f"(original exception: {exc})"
        )

    for name, subparser in subparsers.items():
        # Ensure we don't duplicate arguments
        if not any(action.dest == "spec" for action in getattr(subparser, "_actions", [])):
            try:
                subparser.add_argument(
                    "-s",
                    "--spec",
                    dest="spec",
                    metavar="SPEC",
                    help="specify target address",
                )
            except Exception:
                # Some parsers may not support adding arguments after parsing
                # silently ignore if we cannot add the option
                pass
    return None

