def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Ensure inputs are strings
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be string instances")
    if not root:
        raise ValueError("Root cannot be an empty string")

    # Normalize paths to absolute form
    path_abs = os.path.abspath(path)
    root_abs = os.path.abspath(root)

    # Compute relative path from root to path
    try:
        relative = os.path.relpath(path_abs, root_abs)
    except Exception as exc:
        raise ValueError(f"Unable to compute relative path: {exc}") from exc

    # If the relative path starts with '..', path is not under root
    if relative == ".." or relative.startswith("../"):
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")

    # Handle the case where path == root, relative is '.'
    if relative == ".":
        return ""

    return relative

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings.")
    if not root:
        raise ValueError("Root path cannot be empty.")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    if not norm_path.startswith(norm_root):
        raise ValueError(f"Root '{root}' not found in path '{path}'.")
    remainder = norm_path[len(norm_root):]
    if remainder and remainder[0] == os.sep:
        remainder = remainder[1:]
    return remainder

